param([string]$Root="F:\repos\hitech-os\apps\terminal-de-venta-system",[string]$KeystorePath=$env:PRISMA_ANDROID_KEYSTORE,[switch]$Release,[switch]$VerifyOnly)
Set-StrictMode -Version Latest; $ErrorActionPreference="Stop"; $Stamp=Get-Date -Format "yyMMdd_HHmm"; $LogRoot="F:\descargasf"; if(-not(Test-Path -LiteralPath $LogRoot)){New-Item -ItemType Directory -Force -Path $LogRoot|Out-Null}; $Log=Join-Path $LogRoot "prisma_android_aab_08_int_$Stamp.log"; function L([string]$m){Write-Host $m; Add-Content -LiteralPath $Log -Value ("[{0}] {1}" -f (Get-Date -Format s),$m) -Encoding UTF8}
try{$ResolvedRoot=(Resolve-Path -LiteralPath $Root).Path; $AndroidRoot=Join-Path $ResolvedRoot "products\mobile\android"; $Node=(Get-Command node -ErrorAction Stop).Source; & $Node (Join-Path $AndroidRoot "tools\verify_prisma_app_mobile_08_android_playstore_build_ready.mjs") 2>&1|%{L "verify: $_"}; if($LASTEXITCODE-ne 0){throw "verify failed"}; if($VerifyOnly){exit 0}; if($Release){if(-not $KeystorePath){throw "Release requires KeystorePath or PRISMA_ANDROID_KEYSTORE"}; if(-not(Test-Path -LiteralPath $KeystorePath)){throw "Keystore not found: $KeystorePath"}; if(-not $env:PRISMA_ANDROID_KEYSTORE_PASSWORD){throw "Set PRISMA_ANDROID_KEYSTORE_PASSWORD"}; if(-not $env:PRISMA_ANDROID_KEY_PASSWORD){throw "Set PRISMA_ANDROID_KEY_PASSWORD"}; $env:PRISMA_ANDROID_KEYSTORE=(Resolve-Path -LiteralPath $KeystorePath).Path; $Task=":app:bundleRelease"}else{$Task=":app:bundleDebug"}; $Runner=(Get-Command gradle -ErrorAction SilentlyContinue).Source; if(-not $Runner){throw "gradle not found. Open products\mobile\android in Android Studio or install Gradle."}; Push-Location $AndroidRoot; try{& $Runner $Task "--stacktrace" 2>&1|%{L "gradle: $_"}; if($LASTEXITCODE-ne 0){throw "Gradle failed"}}finally{Pop-Location}; L "bundleOutput=$(Join-Path $AndroidRoot 'app\build\outputs\bundle')"; exit 0}catch{L "ERROR $($_.Exception.Message)"; exit 1}
